import { describe, expect, it } from "vitest";
import {
  compareActivationGaps,
  computeCollectionDigest,
  normalizeAccountAmount,
  normalizeCashPaidCny,
  normalizeDraftItem,
  sortActivationGaps,
  sortUsageRepairBaseline,
  stableStringify,
  summarizeActivationGaps,
  type ActivationDraft,
  type ActivationGap,
  type UsageRepairBaselineRow,
} from "../index.js";

const CUTOVER = "2026-08-31T16:00:00.000Z";
const API_RESOURCE = "11111111-1111-4111-8111-111111111111";
const PLAN_RESOURCE = "22222222-2222-4222-8222-222222222222";
const LEGACY_ID = "66666666-6666-4666-8666-666666666666";
const OTHER_LEGACY_ID = "66666666-6666-4666-8666-666666666667";

function gapOf(overrides: Partial<ActivationGap> = {}): ActivationGap {
  return {
    code: "UNKNOWN_COST", category: "USAGE", message: "用量费用状态未明确",
    resourceId: null, accountCurrency: null, legacyRecordId: null, ledgerLineId: null,
    month: null, detail: null, ...overrides,
  };
}

describe("缺口摘要与确定性排序", () => {
  it("比较键完全相同时视为等价（detail 不参与排序）", () => {
    expect(compareActivationGaps(gapOf({ detail: "左" }), gapOf({ detail: "右" }))).toBe(0);
    expect(sortActivationGaps([gapOf({ detail: "左" }), gapOf({ detail: "右" })])).toHaveLength(2);
  });

  it("比较键不同时给出 -1 / 1，且空值按空串参与比较", () => {
    expect(compareActivationGaps(gapOf({ code: "MISSING_API_CURRENCY" }), gapOf({ code: "UNKNOWN_COST" })))
      .toBe(-1);
    expect(compareActivationGaps(gapOf({ code: "UNKNOWN_COST" }), gapOf({ code: "MISSING_API_CURRENCY" })))
      .toBe(1);
    expect(compareActivationGaps(gapOf({ resourceId: null }), gapOf({ resourceId: API_RESOURCE }))).toBe(-1);
  });

  it("按 code 归并计数并稳定排序", () => {
    const summary = summarizeActivationGaps([
      gapOf({ code: "UNKNOWN_COST" }),
      gapOf({ code: "UNKNOWN_COST" }),
      gapOf({ code: "NEGATIVE_BALANCE" }),
    ]);
    expect(summary).toEqual([
      { code: "NEGATIVE_BALANCE", count: 1 },
      { code: "UNKNOWN_COST", count: 2 },
    ]);
    expect(summarizeActivationGaps([])).toEqual([]);
  });

  it("修复基准行按主键排序且不修改入参顺序", () => {
    const row = (ledgerLineId: string): UsageRepairBaselineRow => ({
      ledgerLineId, eligibleRepairs: ["settled_at"],
      targetFieldsBeforeHash: "a".repeat(64), nonTargetFieldsBeforeHash: "b".repeat(64),
    });
    const input = [row("cccccccc-0000-4000-8000-000000000003"), row("aaaaaaaa-0000-4000-8000-000000000001")];
    expect(sortUsageRepairBaseline(input).map((entry) => entry.ledgerLineId)).toEqual([
      "aaaaaaaa-0000-4000-8000-000000000001", "cccccccc-0000-4000-8000-000000000003",
    ]);
    expect(input[0]!.ledgerLineId).toBe("cccccccc-0000-4000-8000-000000000003");
  });
});

describe("稳定序列化与集合摘要", () => {
  it("非有限数值不得进入稳定序列化", () => {
    expect(() => stableStringify({ amount: Number.POSITIVE_INFINITY })).toThrow(/非有限数值/);
  });

  it("集合摘要与对象键顺序无关，且对内容敏感", () => {
    const left = computeCollectionDigest([{ b: 1, a: 2 }, null]);
    expect(left).toMatch(/^[a-f0-9]{64}$/);
    expect(computeCollectionDigest([{ a: 2, b: 1 }, null])).toBe(left);
    expect(computeCollectionDigest([{ a: 2, b: 1 }])).not.toBe(left);
  });
});

describe("金额规范化拒绝非法十进制", () => {
  it("非数字字符串在规范化入口失败关闭", () => {
    expect(() => normalizeAccountAmount("abc")).toThrow(/不是合法十进制数/);
    expect(() => normalizeCashPaidCny("abc")).toThrow(/不是合法十进制数/);
  });
});

describe("草稿规范化排序", () => {
  it("多行草稿按业务键稳定排序（覆盖全部次序比较键）", () => {
    const recharge = (
      occurredAt: string, sourceRecordId: string, key: string,
    ): ActivationDraft["historical_api_recharges"][number] => ({
      resource_id: API_RESOURCE, account_currency: "CNY", account_amount: "1",
      cash_paid_cny: "1.00", occurred_at: occurredAt, external_reference: "R",
      description: "充值", evidence_ref: "evidence://r", source_record_id: sourceRecordId,
      record_idempotency_key: key,
    });
    const planPurchase = (
      productName: string, sourceRecordId: string | null, key: string,
    ): ActivationDraft["coding_plan_purchases"][number] => ({
      resource_id: PLAN_RESOURCE, kind: "PURCHASE", product_name: productName,
      account_amount: "1", account_currency: "CNY", cash_paid_cny: "1.00",
      service_period_start: "2026-09-20", service_period_end: "2026-10-19",
      occurred_at: "2026-09-20T02:00:00.000Z", external_reference: "P", auto_renew: true,
      description: "购买", evidence_ref: "evidence://p", source_record_id: sourceRecordId,
      carryover_snapshot_id: null, record_idempotency_key: key,
    });
    const carryoverItem = (
      periodStart: string, periodEnd: string, snapshotId: string,
    ): ActivationDraft["coding_plan_carryovers"][number] => ({
      resource_id: PLAN_RESOURCE, product_name: "套餐", period_start: periodStart,
      period_end: periodEnd, snapshot_id: snapshotId, description: "跨切换周期",
      evidence_ref: "evidence://c",
    });
    const draft: ActivationDraft = {
      schema_version: "1",
      api_opening_balances: [
        { resource_id: API_RESOURCE, account_currency: "USD", account_amount: "10",
          occurred_at: CUTOVER, description: "期初", evidence_ref: "evidence://o1",
          source_record_id: null },
        { resource_id: API_RESOURCE, account_currency: "CNY", account_amount: "20",
          occurred_at: CUTOVER, description: "期初", evidence_ref: "evidence://o2",
          source_record_id: null },
      ],
      historical_api_recharges: [
        recharge("2026-09-06T02:00:00.000Z", LEGACY_ID, "k-3"),
        recharge("2026-09-05T02:00:00.000Z", OTHER_LEGACY_ID, "k-2"),
        recharge("2026-09-05T02:00:00.000Z", LEGACY_ID, "k-1"),
      ],
      historical_api_costs: [],
      coding_plan_purchases: [
        planPurchase("A", LEGACY_ID, "k-6"),
        planPurchase("B", null, "k-5"),
        planPurchase("A", null, "k-4"),
      ],
      coding_plan_carryovers: [
        carryoverItem("2026-09-10", "2026-10-09", "s-2"),
        carryoverItem("2026-08-10", "2026-09-09", "s-1"),
      ],
      legacy_purchase_resolutions: [
        { legacy_record_id: LEGACY_ID, resource_id: PLAN_RESOURCE, resolution: "MIGRATED",
          finance_event_id: null, migrated_external_reference: "x", reason: null, evidence_ref: null },
        { legacy_record_id: LEGACY_ID, resource_id: API_RESOURCE, resolution: "MIGRATED",
          finance_event_id: null, migrated_external_reference: "x", reason: null, evidence_ref: null },
      ],
    };
    const candidate = normalizeDraftItem(draft, "77777777-7777-4777-8777-777777777777");
    expect(candidate.apiOpeningBalances.map((row) => row.accountCurrency)).toEqual(["CNY", "USD"]);
    expect(candidate.historicalApiRecharges.map((row) => row.recordIdempotencyKey))
      .toEqual(["k-1", "k-2", "k-3"]);
    expect(candidate.codingPlanPurchases.map((row) => row.recordIdempotencyKey))
      .toEqual(["k-4", "k-5", "k-6"]);
    expect(candidate.codingPlanCarryovers.map((row) => row.snapshotId)).toEqual(["s-1", "s-2"]);
    expect(candidate.legacyPurchaseResolutions.map((row) => row.resourceId))
      .toEqual([API_RESOURCE, PLAN_RESOURCE]);
  });
});

src/__tests__/resource-lifecycle.test.ts.source:
/**
 * W11 单元测试：资源池状态机（resource-lifecycle）纯函数。
 *
 * 覆盖：
 *   - 处置矩阵：401→CREDENTIAL_INVALID、402→EXHAUSTED、429→冷却退避、临时故障→熔断阈值
 *   - 退避计算：指数增长、封顶、确定性（同输入同输出，可回放）
 *   - 成功路径：计数清零、UNAVAILABLE 半开成功→DEGRADED（一次成功不抹趋势）
 *   - 准入门禁：ACTIVE/DEGRADED 放行、冷却中拒绝、冷却到期半开探测、终态隔离拒绝
 *   - 幂等：隔离态重复事件不重复迁移
 *   - 恢复边界：终态默认人工恢复；Coding Plan 厂商额度强证据可自动恢复
 *
 * 依据：TRD §9 行 585-598、§5.4 行 243-249；WT-07/19。
 */
import { describe, it, expect } from "vitest";
import {
  RESOURCE_STATUS,
  STATE_REASON,
  RESOURCE_POOL_POLICY,
  computeCooldownMs,
  worstResourceStatus,
  deriveResourceTransition,
  deriveSuccessTransition,
  deriveCredentialExpiry,
  deriveRefreshFailure,
  deriveAdminRecovery,
  deriveQuotaSyncRecovery,
  deriveBalanceSyncRecovery,
  evaluateAdmission,
  type ResourceRuntimeState,
} from "../index.js";

const T0 = 1_800_000_000_000; // 固定时钟（可回放）

function active(overrides: Partial<ResourceRuntimeState> = {}): ResourceRuntimeState {
  return { status: RESOURCE_STATUS.ACTIVE, consecutiveFailures: 0, cooldownUntil: null, ...overrides };
}

describe("computeCooldownMs 指数退避", () => {
  it("混合资源取唯一最严重状态", () => {
    expect(worstResourceStatus(["ACTIVE", "DEGRADED", "RATE_LIMITED"])).toBe("RATE_LIMITED");
    expect(worstResourceStatus(["EXHAUSTED", "CREDENTIAL_INVALID", "EXPIRED"])).toBe("CREDENTIAL_INVALID");
    expect(worstResourceStatus([])).toBe("ACTIVE");
  });
  it("指数增长且确定性", () => {
    expect(computeCooldownMs(1, 30_000, 1_800_000)).toBe(30_000);
    expect(computeCooldownMs(2, 30_000, 1_800_000)).toBe(60_000);
    expect(computeCooldownMs(3, 30_000, 1_800_000)).toBe(120_000);
    expect(computeCooldownMs(4, 30_000, 1_800_000)).toBe(240_000);
    // 同输入同输出（无随机抖动，可回放）
    expect(computeCooldownMs(3, 30_000, 1_800_000)).toBe(computeCooldownMs(3, 30_000, 1_800_000));
  });

  it("封顶 cap", () => {
    expect(computeCooldownMs(100, 30_000, 1_800_000)).toBe(1_800_000);
  });
});

describe("deriveResourceTransition 处置矩阵（TRD §9）", () => {
  it("401/403 → CREDENTIAL_INVALID 隔离（仅人工恢复）", () => {
    const t = deriveResourceTransition(active(), "UPSTREAM_CREDENTIAL_INVALID", T0);
    expect(t).not.toBeNull();
    expect(t!.toStatus).toBe(RESOURCE_STATUS.CREDENTIAL_INVALID);
    expect(t!.reason).toBe(STATE_REASON.CREDENTIAL_REJECTED);
    expect(t!.isolates).toBe(true);
    expect(t!.cooldownUntil).toBeNull();
  });

  it("402 → EXHAUSTED 隔离", () => {
    const t = deriveResourceTransition(active(), "UPSTREAM_BILLING_BLOCKED", T0);
    expect(t!.toStatus).toBe(RESOURCE_STATUS.EXHAUSTED);
    expect(t!.reason).toBe(STATE_REASON.BILLING_BLOCKED);
    expect(t!.isolates).toBe(true);
  });

  it("429 立即进入短时 RATE_LIMITED，保留 Retry-After 且同波并发去重", () => {
    const t1 = deriveResourceTransition(
      active(),
      "UPSTREAM_RATE_LIMITED",
      T0,
      { retryAfterMs: 12_000 },
    );
    expect(t1!.toStatus).toBe(RESOURCE_STATUS.RATE_LIMITED);
    expect(t1!.reason).toBe(STATE_REASON.RATE_LIMITED);
    expect(t1!.cooldownUntil).toBe(T0 + 12_000);
    expect(t1!.isolates).toBe(true);
    expect(t1!.consecutiveFailures).toBe(1);

    const cooling = active({
      status: RESOURCE_STATUS.RATE_LIMITED,
      consecutiveFailures: 1,
      cooldownUntil: T0 + 12_000,
    });
    expect(deriveResourceTransition(
      cooling,
      "UPSTREAM_RATE_LIMITED",
      T0 + 1_000,
      { retryAfterMs: 60_000 },
    )).toBeNull();

    const nextWave = deriveResourceTransition(
      cooling,
      "UPSTREAM_RATE_LIMITED",
      T0 + 12_000,
      { retryAfterMs: 2_000 },
    );
    expect(nextWave!.toStatus).toBe(RESOURCE_STATUS.RATE_LIMITED);
    expect(nextWave!.consecutiveFailures).toBe(2);
    expect(nextWave!.cooldownUntil).toBe(T0 + 14_000);
  });

  it("厂商精确重置时间不受通用 30 分钟冷却上限截断", () => {
    const resetAt = T0 + 4 * 60 * 60_000;
    const transition = deriveResourceTransition(
      active(), "UPSTREAM_RATE_LIMITED", T0, { cooldownUntil: resetAt },
    );
    expect(transition?.cooldownUntil).toBe(resetAt);
  });

  it("异常远期厂商时间按五小时窗口可信上限重新确认", () => {
    const transition = deriveResourceTransition(
      active(),
      "UPSTREAM_RATE_LIMITED",
      T0,
      { cooldownUntil: T0 + 30 * 24 * 60 * 60_000 },
    );
    expect(transition?.cooldownUntil).toBe(
      T0 + RESOURCE_POOL_POLICY.providerWindowCooldownMaxMs,
    );
  });

  it("临时故障达到旧阈值后仍保持 DEGRADED + ALLOW", () => {
    const t1 = deriveResourceTransition(active(), "UPSTREAM_TEMPORARY", T0);
    expect(t1!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t1!.reason).toBe(STATE_REASON.PASSIVE_FAILURE);
    expect(t1!.consecutiveFailures).toBe(1);
    expect(t1!.isolates).toBe(false);

    const t2 = deriveResourceTransition(
      active({ status: RESOURCE_STATUS.DEGRADED, consecutiveFailures: RESOURCE_POOL_POLICY.failureThreshold - 1 }),
      "UPSTREAM_TEMPORARY",
      T0,
    );
    expect(t2!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t2!.reason).toBe(STATE_REASON.PASSIVE_FAILURE);
    expect(t2!.isolates).toBe(false);
    expect(t2!.cooldownUntil).toBeNull();
  });

  it("TRANSPORT_ERROR 与 UNKNOWN 只计入健康降级", () => {
    const t = deriveResourceTransition(
      active({ consecutiveFailures: RESOURCE_POOL_POLICY.failureThreshold - 1 }),
      "TRANSPORT_ERROR",
      T0,
    );
    expect(t!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t!.isolates).toBe(false);
  });

  it("客户端/能力/下游/账本错误不计入资源健康", () => {
    for (const c of ["CLIENT_INVALID", "CAPABILITY_UNSUPPORTED", "DOWNSTREAM_AUTH_OR_QUOTA", "LEDGER_FAILURE", "STREAM_INTERRUPTED_AFTER_COMMIT"] as const) {
      expect(deriveResourceTransition(active(), c, T0)).toBeNull();
    }
  });

  it("幂等：CREDENTIAL_INVALID 重复 401 不重复迁移；终态隔离忽略临时故障", () => {
    const isolated = active({ status: RESOURCE_STATUS.CREDENTIAL_INVALID, consecutiveFailures: 1 });
    expect(deriveResourceTransition(isolated, "UPSTREAM_CREDENTIAL_INVALID", T0)).toBeNull();
    expect(deriveResourceTransition(isolated, "UPSTREAM_TEMPORARY", T0)).toBeNull();
    expect(deriveResourceTransition(isolated, "UPSTREAM_RATE_LIMITED", T0)).toBeNull();
    const exhausted = active({ status: RESOURCE_STATUS.EXHAUSTED });
    expect(deriveResourceTransition(exhausted, "UPSTREAM_BILLING_BLOCKED", T0)).toBeNull();
  });
});

describe("deriveSuccessTransition 成功路径", () => {
  it("ACTIVE 无失败 → 无迁移", () => {
    expect(deriveSuccessTransition(active())).toBeNull();
  });

  it("DEGRADED 成功 → ACTIVE 清零", () => {
    const t = deriveSuccessTransition(active({ status: RESOURCE_STATUS.DEGRADED, consecutiveFailures: 2 }));
    expect(t!.toStatus).toBe(RESOURCE_STATUS.ACTIVE);
    expect(t!.consecutiveFailures).toBe(0);
    expect(t!.reason).toBe(STATE_REASON.PASSIVE_SUCCESS);
  });

  it("UNAVAILABLE 半开探测成功 → DEGRADED（一次成功不抹掉长期趋势）", () => {
    const t = deriveSuccessTransition(
      active({ status: RESOURCE_STATUS.UNAVAILABLE, consecutiveFailures: 3, cooldownUntil: T0 - 1 }),
    );
    expect(t!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
    expect(t!.reason).toBe(STATE_REASON.HALF_OPEN_PROBE_OK);
    expect(t!.consecutiveFailures).toBe(0);
  });

  it("RATE_LIMITED 半开探测成功 → DEGRADED 并清除冷却", () => {
    const t = deriveSuccessTransition(
      active({ status: RESOURCE_STATUS.RATE_LIMITED, consecutiveFailures: 1, cooldownUntil: T0 - 1 }),
    );
    expect(t).toMatchObject({
      toStatus: RESOURCE_STATUS.DEGRADED,
      reason: STATE_REASON.HALF_OPEN_PROBE_OK,
      consecutiveFailures: 0,
      cooldownUntil: null,
    });
  });

  it("终态隔离资源成功被防御性忽略", () => {
    expect(deriveSuccessTransition(active({ status: RESOURCE_STATUS.CREDENTIAL_INVALID }))).toBeNull();
    expect(deriveSuccessTransition(active({ status: RESOURCE_STATUS.EXHAUSTED }))).toBeNull();
  });
});

describe("deriveQuotaSyncRecovery 厂商额度证据恢复", () => {
  it.each(["RATE_LIMITED", "EXHAUSTED"] as const)(
    "%s 在额度接口确认恢复后进入 DEGRADED",
    (status) => {
      expect(deriveQuotaSyncRecovery(active({
        status, consecutiveFailures: 3, cooldownUntil: T0 + 10_000,
      }))).toMatchObject({
        toStatus: "DEGRADED",
        reason: "QUOTA_SYNC_RECOVERED",
        consecutiveFailures: 0,
        cooldownUntil: null,
      });
    },
  );

  it("健康态不产生恢复事件", () => {
    expect(deriveQuotaSyncRecovery(active())).toBeNull();
  });

  it("CREDENTIAL_INVALID 不因额度接口成功而解除隔离", () => {
    expect(deriveQuotaSyncRecovery(active({
      status: RESOURCE_STATUS.CREDENTIAL_INVALID,
      consecutiveFailures: 3,
      cooldownUntil: T0 + 10_000,
    }))).toBeNull();
  });
});

describe("deriveBalanceSyncRecovery API 余额证据恢复", () => {
  it("EXHAUSTED 在厂商确认正余额后进入 DEGRADED", () => {
    expect(deriveBalanceSyncRecovery(active({
      status: RESOURCE_STATUS.EXHAUSTED, consecutiveFailures: 2,
    }))).toMatchObject({
      toStatus: "DEGRADED", reason: "BALANCE_SYNC_RECOVERED",
      consecutiveFailures: 0, cooldownUntil: null, isolates: false,
    });
  });

  it("EXHAUSTED 以外的状态不由余额快照改写", () => {
    expect(deriveBalanceSyncRecovery(active())).toBeNull();
    expect(deriveBalanceSyncRecovery(active({ status: RESOURCE_STATUS.DEGRADED }))).toBeNull();
  });
});

describe("evaluateAdmission 准入门禁（硬过滤）", () => {
  it("ACTIVE / DEGRADED 放行", () => {
    expect(evaluateAdmission(active(), T0).admit).toBe(true);
    expect(evaluateAdmission(active({ status: RESOURCE_STATUS.DEGRADED }), T0).admit).toBe(true);
  });

  it("UNAVAILABLE 冷却中拒绝；冷却到期允许半开探测", () => {
    const cooling = active({ status: RESOURCE_STATUS.UNAVAILABLE, cooldownUntil: T0 + 10_000 });
    const blocked = evaluateAdmission(cooling, T0);
    expect(blocked.admit).toBe(false);
    expect(blocked.blockReason).toBe(RESOURCE_STATUS.UNAVAILABLE);

    const probe = evaluateAdmission(cooling, T0 + 10_000);
    expect(probe.admit).toBe(true);
    expect(probe.probe).toBe(true);
  });

  it("RATE_LIMITED 冷却中保留限流语义；到期允许半开探测", () => {
    const cooling = active({ status: RESOURCE_STATUS.RATE_LIMITED, cooldownUntil: T0 + 10_000 });
    expect(evaluateAdmission(cooling, T0)).toEqual({
      admit: false,
      probe: false,
      blockReason: RESOURCE_STATUS.RATE_LIMITED,
    });
    expect(evaluateAdmission(cooling, T0 + 10_000)).toEqual({
      admit: true,
      probe: true,
      blockReason: null,
    });
  });

  it("终态隔离（CREDENTIAL_INVALID/EXHAUSTED/EXPIRED）拒绝", () => {
    for (const s of [RESOURCE_STATUS.CREDENTIAL_INVALID, RESOURCE_STATUS.EXHAUSTED, RESOURCE_STATUS.EXPIRED] as const) {
      const r = evaluateAdmission(active({ status: s }), T0);
      expect(r.admit).toBe(false);
      expect(r.blockReason).toBe(s);
    }
  });
});

describe("凭证生命周期（WT-19）", () => {
  it("deriveCredentialExpiry：到期 → EXPIRED；未到期/已隔离 → 无迁移", () => {
    expect(deriveCredentialExpiry(active(), T0 + 1, T0)).toBeNull(); // 未到期
    expect(deriveCredentialExpiry(active(), null, T0)).toBeNull(); // 无过期时间（API_KEY）
    const t = deriveCredentialExpiry(active(), T0, T0);
    expect(t!.toStatus).toBe(RESOURCE_STATUS.EXPIRED);
    expect(t!.reason).toBe(STATE_REASON.CREDENTIAL_EXPIRED);
    expect(t!.isolates).toBe(true);
    // 幂等
    expect(deriveCredentialExpiry(active({ status: RESOURCE_STATUS.EXPIRED }), T0, T0 + 1)).toBeNull();
  });

  it("deriveRefreshFailure：刷新失败 → CREDENTIAL_INVALID 隔离；幂等", () => {
    const t = deriveRefreshFailure(active());
    expect(t!.toStatus).toBe(RESOURCE_STATUS.CREDENTIAL_INVALID);
    expect(t!.reason).toBe(STATE_REASON.REFRESH_FAILED);
    expect(deriveRefreshFailure(active({ status: RESOURCE_STATUS.CREDENTIAL_INVALID }))).toBeNull();
  });

  it("deriveAdminRecovery：仅隔离态可恢复，恢复到 DEGRADED（受控）", () => {
    expect(deriveAdminRecovery(active())).toBeNull(); // ACTIVE 不可"恢复"
    expect(deriveAdminRecovery(active({ status: RESOURCE_STATUS.DEGRADED }))).toBeNull();
    for (const s of [RESOURCE_STATUS.CREDENTIAL_INVALID, RESOURCE_STATUS.EXHAUSTED, RESOURCE_STATUS.EXPIRED, RESOURCE_STATUS.UNAVAILABLE] as const) {
      const t = deriveAdminRecovery(active({ status: s, consecutiveFailures: 5 }));
      expect(t!.toStatus).toBe(RESOURCE_STATUS.DEGRADED);
      expect(t!.reason).toBe(STATE_REASON.ADMIN_RECOVER);
      expect(t!.consecutiveFailures).toBe(0);
    }
  });
});

src/__tests__/reconciliation.test.ts.source:
/**
 * W17 单元测试：对账判定（evaluateReconciliation）。
 *
 * 覆盖：
 *   - PASS：重复 0 + 丢失 0 + 无汇总不一致
 *   - FAIL：重复 >0（重复率必须 0，行 870）
 *   - FAIL：丢失率 ≥0.1%（行 871）
 *   - REVIEW：仅汇总不一致（MISMATCH）
 *   - severity 分级（重复/丢失=HIGH，汇总=MEDIUM）
 *   - 比率计算（decimal 字符串）
 *
 * 依据：TRD 行 870-871、857。
 */
import { describe, it, expect } from "vitest";
import {
  evaluateReconciliation,
  DISCREPANCY_TYPE,
  RECONCILIATION_RESULT,
  DISCREPANCY_SEVERITY,
  type ReconciliationScan,
} from "../index.js";

function scan(overrides: Partial<ReconciliationScan> = {}): ReconciliationScan {
  return {
    rangeFrom: 1_800_000_000_000,
    rangeTo: 1_800_086_400_000,
    requestsScanned: 100,
    usageEventsScanned: 100,
    ledgerLinesScanned: 100,
    transactionsScanned: 100,
    discrepancies: [],
    ...overrides,
  };
}

function discrepancy(type: keyof typeof DISCREPANCY_TYPE, extra: Partial<{ aiRequestId: string; usageEventId: string }> = {}) {
  return {
    type: DISCREPANCY_TYPE[type],
    aiRequestId: extra.aiRequestId ?? null,
    usageEventId: extra.usageEventId ?? null,
    ledgerLineId: null,
    ledgerTransactionId: null,
    detail: {},
  };
}

describe("evaluateReconciliation 对账判定", () => {
  it("PASS：无任何差异（重复 0 + 丢失 0 + 无汇总不一致）", () => {
    const v = evaluateReconciliation(scan());
    expect(v.result).toBe(RECONCILIATION_RESULT.PASS);
    expect(v.duplicateCount).toBe(0);
    expect(v.missingCount).toBe(0);
    expect(v.mismatchCount).toBe(0);
    expect(v.duplicateRate).toBe("0.00000000");
    expect(v.missingRate).toBe("0.00000000");
  });

  it("FAIL：重复 >0（重复率必须 0，TRD 行 870）", () => {
    const v = evaluateReconciliation(
      scan({ discrepancies: [discrepancy("DUPLICATE_USAGE", { usageEventId: "u1" })] }),
    );
    expect(v.result).toBe(RECONCILIATION_RESULT.FAIL);
    expect(v.duplicateCount).toBe(1);
    expect(v.duplicateRate).toBe("0.01000000"); // 1/100
  });

  it("FAIL：丢失率 ≥0.1%（TRD 行 871，阈值 0.001）", () => {
    // 100 个 usage，1 个丢失 = 0.01 ≥ 0.001 → FAIL
    const v = evaluateReconciliation(
      scan({ discrepancies: [discrepancy("MISSING_LEDGER_LINE", { usageEventId: "u1" })] }),
    );
    expect(v.result).toBe(RECONCILIATION_RESULT.FAIL);
    expect(v.missingCount).toBe(1);
    expect(v.missingRate).toBe("0.01000000");
  });

  it("边界：丢失率恰好 0.1% → 仍 FAIL（阈值是 <，非 ≤）", () => {
    // 1000 个 usage，1 个丢失 = 0.001 = 阈值 → FAIL（行 871 是"低于 0.1%"，即严格 <）
    const v = evaluateReconciliation(
      scan({
        usageEventsScanned: 1000,
        discrepancies: [discrepancy("MISSING_LEDGER_LINE", { usageEventId: "u1" })],
      }),
    );
    expect(v.result).toBe(RECONCILIATION_RESULT.FAIL);
    expect(v.missingRate).toBe("0.00100000");
  });

  it("PASS 边界：丢失率 <0.1%（如 9999 个 usage，1 个丢失 ≈ 0.0001）", () => {
    const v = evaluateReconciliation(
      scan({
        usageEventsScanned: 9999,
        discrepancies: [discrepancy("MISSING_LEDGER_LINE", { usageEventId: "u1" })],
      }),
    );
    expect(v.result).toBe(RECONCILIATION_RESULT.PASS);
    expect(v.missingCount).toBe(1); // 有丢失但未超阈值
  });

  it("REVIEW：仅汇总不一致（无重复/丢失）", () => {
    const v = evaluateReconciliation(
      scan({ discrepancies: [discrepancy("SETTLEMENT_MISMATCH" as keyof typeof DISCREPANCY_TYPE)] }),
    );
    expect(v.result).toBe(RECONCILIATION_RESULT.REVIEW);
    expect(v.mismatchCount).toBe(1);
    expect(v.duplicateCount).toBe(0);
    expect(v.missingCount).toBe(0);
  });

  it("severity 分级：重复/丢失 = HIGH，汇总不一致 = MEDIUM", () => {
    const v = evaluateReconciliation(
      scan({
        discrepancies: [
          discrepancy("DUPLICATE_USAGE", { usageEventId: "u1" }),
          discrepancy("MISSING_LEDGER_LINE", { usageEventId: "u2" }),
          discrepancy("ORPHAN_LEDGER_LINE"),
          discrepancy("SETTLEMENT_MISMATCH" as keyof typeof DISCREPANCY_TYPE),
        ],
      }),
    );
    const sev = v.discrepancies.map((d) => d.severity);
    expect(sev).toContain(DISCREPANCY_SEVERITY.HIGH);
    expect(sev).toContain(DISCREPANCY_SEVERITY.MEDIUM);
    // 重复/丢失类都是 HIGH
    expect(v.discrepancies.filter((d) => d.type === DISCREPANCY_TYPE.SETTLEMENT_MISMATCH)[0]!.severity).toBe(
      DISCREPANCY_SEVERITY.MEDIUM,
    );
    expect(v.discrepancies.filter((d) => d.type === DISCREPANCY_TYPE.DUPLICATE_USAGE)[0]!.severity).toBe(
      DISCREPANCY_SEVERITY.HIGH,
    );
  });

  it("重复 + 丢失同时存在 → FAIL（重复优先触发）", () => {
    const v = evaluateReconciliation(
      scan({
        discrepancies: [
          discrepancy("DUPLICATE_USAGE", { usageEventId: "u1" }),
          discrepancy("MISSING_LEDGER_LINE", { usageEventId: "u2" }),
        ],
      }),
    );
    expect(v.result).toBe(RECONCILIATION_RESULT.FAIL);
    expect(v.duplicateCount).toBe(1);
    expect(v.missingCount).toBe(1);
  });

  it("usageEventsScanned=0 时不除零（比率 0，PASS）", () => {
    const v = evaluateReconciliation(scan({ usageEventsScanned: 0, discrepancies: [] }));
    expect(v.result).toBe(RECONCILIATION_RESULT.PASS);
    expect(v.duplicateRate).toBe("0.00000000");
    expect(v.missingRate).toBe("0.00000000");
  });

  it("totalDiscrepancies 统计全部差异类型", () => {
    const v = evaluateReconciliation(
      scan({
        discrepancies: [
          discrepancy("DUPLICATE_USAGE", { usageEventId: "u1" }),
          discrepancy("SETTLEMENT_MISMATCH" as keyof typeof DISCREPANCY_TYPE),
        ],
      }),
    );
    expect(v.totalDiscrepancies).toBe(2);
  });
});

